#include "powder/process.hpp"
#include <iostream>
using namespace powder;
void check(bool b,const char* s){if(!b)throw std::runtime_error(s);}
template<class F>void rejects(F f){bool failed=false;try{f();}catch(const std::exception&){failed=true;}check(failed,"invalid handoff accepted");}
int main(){try{ClumpWorld base;MaterialContact m;m.law=ContactLaw::Linear;m.linear={1000,.01,250,.0025,.4};base.pair_models={{{0,0},m},{{0,1},m},{{1,1},m}};base.wall_models={{0,m},{1,m}};base.planes={{1,{0,0,1},0}};std::vector<ProcessRegion> regions;for(unsigned i=0;i<5;++i)regions.push_back({static_cast<ProcessStage>(i),base});std::vector<ParticleId> ids;for(unsigned i=0;i<8;++i){auto b=make_clump(i+1,i%2,{{{},.002}},1500+i*100);b.position_m={i*.01,0,.00101};regions[0].world.bodies.push_back(b);ids.push_back(b.id);}auto mono=regions[0].world;ProcessChain chain(regions);const double dt=1e-7;
 for(unsigned stage=0;stage<4;++stage){for(unsigned i=0;i<20;++i){chain.advance(dt);mono.step(dt);}double mass=0,energy=0;std::map<std::uint32_t,double> groups;for(const auto& b:mono.bodies){mass+=clump_properties(b.pebbles,b.density_kg_m3).mass_kg;groups[b.type]+=clump_properties(b.pebbles,b.density_kg_m3).mass_kg;energy+=clump_kinetic_energy(b);}auto receipt=chain.handoff(stage,stage+1,ids,chain.time_s(),stage+1);check(receipt.group_mass==groups,"group composition changed");check(std::abs(receipt.mass_kg-mass)<1e-15&&std::abs(receipt.kinetic_j-energy)<1e-20&&receipt.external_work_j==0,"handoff mass/energy");check(serialize_clump_state(chain.regions()[stage+1].world)==serialize_clump_state(mono),"handoff changed physical state");rejects([&]{chain.handoff(stage,stage+1,ids,chain.time_s(),stage+1);});}
 for(unsigned i=0;i<15000;++i){chain.advance(dt);mono.step(dt);}check(serialize_clump_state(chain.regions()[4].world)==serialize_clump_state(mono),"full chain differs from monolithic after floor impact");check(chain.regions()[4].world.histories()>0,"contact comparison not exercised");for(const auto& e:chain.residence()){double sum=0;for(double t:e.second.seconds)sum+=t;check(std::abs(sum-chain.time_s())<1e-15&&e.second.owner==4,"residence not conserved");}
 ProcessChain fresh(regions);rejects([&]{fresh.handoff(0,1,ids,-1,1);});rejects([&]{fresh.handoff(0,1,{1,1},0,1);});rejects([&]{fresh.handoff(0,2,ids,0,1);});rejects([&]{fresh.handoff(0,1,{999},0,1);});check(fresh.receipts().empty()&&fresh.regions()[0].world.bodies.size()==8,"failed handoff mutated state");
 auto contact=regions;contact[0].world.bodies[0].position_m.z=.000999;ProcessChain active(contact);rejects([&]{active.handoff(0,1,ids,0,1);});check(active.regions()[0].world.bodies.size()==8,"contact handoff lost bodies");
 auto split=regions;split[1].world.bodies.push_back(split[0].world.bodies.back());split[0].world.bodies.pop_back();split[1].world.bodies[0].position_m=split[0].world.bodies[0].position_m;rejects([&]{ProcessChain invalid(split);});std::cout<<"PASS five-stage q1 exact monolithic parity, floor contact, mass/composition/energy/residence, replay/time/ID/contact guards\n";
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
